import torch

class ExportableModel(torch.nn.Module):
    def forward(self, x):
        return torch.cond(
            x.sum() > 0,
            lambda value: value.relu(),
            lambda value: (-value).relu(),
            (x,),
        )

model = ExportableModel().eval()
batch = torch.export.Dim("batch", min=1, max=64)
example = torch.randn(4, 10)
program = torch.export.export(
    model,
    (example,),
    dynamic_shapes={"x": {0: batch}},
)
exported_module = program.module()
for batch_size in (1, 4, 64):
    for sign in (-1.0, 1.0):
        test_input = torch.full((batch_size, 10), sign)
        torch.testing.assert_close(exported_module(test_input), model(test_input))

import torch

def load_for_inference(
    path, device, build_model, checkpoint_key=None
):
    device = torch.device(device)
    model = build_model()
    artifact = torch.load(path, map_location="cpu", weights_only=True)
    state_dict = artifact if checkpoint_key is None else artifact[checkpoint_key]
    model.load_state_dict(state_dict, strict=True)
    return model.to(device).eval()

@torch.inference_mode()
def predict_logits(model, validated_batch, device):
    device = torch.device(device)
    batch = validated_batch.to(device)
    return model(batch)

